  CUtensorMap mW, mE;
  cuuint64_t dW[3] = {(cuuint64_t)kBK, (cuuint64_t)kN, (cuuint64_t)kKB}, sW[2] = {(cuuint64_t)kD * 4, (cuuint64_t)kBK * 4};
  cuuint32_t bW[3] = {kBK, kRows, 1}, es[3] = {1, 1, 1};
  if (cuTensorMapEncodeTiled(&mW, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 3, (void*)W, dW, sW, bW, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 421;
  cuuint64_t dE[2] = {(cuuint64_t)kD, (cuuint64_t)B}, sE[1] = {(cuuint64_t)kD * 4};
  cuuint32_t bE[2] = {kBK, (cuuint32_t)half};
  if (cuTensorMapEncodeTiled(&mE, CU_TENSOR_MAP_DATA_TYPE_TFLOAT32, 2, (void*)emb, dE, sE, bE, es, CU_TENSOR_MAP_INTERLEAVE_NONE,
      CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_256B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE) != CUDA_SUCCESS) return 422;
  static bool attr = false;
  if (!attr) { cudaFuncSetAttribute(tc_pair2_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, kSmemDyn); attr = true; }
  OutPtrs op; for (int i = 0; i < 6; ++i) op.p[i] = outs[i];
  cudaLaunchConfig_t cfg = {};
  cfg.gridDim = dim3(2 * kWTiles * nb); cfg.blockDim = dim3(128); cfg.dynamicSmemBytes = stages * perK + 1024; cfg.stream = stream;
  cudaLaunchAttribute at[1]; at[0].id = cudaLaunchAttributeClusterDimension; at[0].val.clusterDim.x = 2; at[0].val.clusterDim.y = 1; at[0].val.clusterDim.z = 1;
  cfg.attrs = at; cfg.numAttrs = 1;
  cudaLaunchKernelEx(&cfg, tc_pair2_kernel, mW, mE, bias, op, B, Ntile, nb, stages, order, whint, nomma, prof);
  return (int)cudaGetLastError();
}
extern "C" int tc_pair2_stages(int B, int nb) { const int Ntile = ((B + nb - 1) / nb + 15) / 16 * 16; return (kSmemDyn - 1024) / (kWBlk + Ntile / 2 * 128); }
'''
open('/tmp/e2/tc_pair2.cu','w').write(src)
r = subprocess.run('cd /tmp/e2 && nvcc -O3 -std=c++17 -shared -Xcompiler -fPIC -gencode arch=compute_100a,code=sm_100a tc_pair2.cu -o tc_pair2.so -lcuda', shell=True, capture_output=True, text=True)
print(r.returncode, r.stderr[-3000:])
import ctypes, torch, numpy as np
lib = ctypes.CDLL('/tmp/e2/tc_pair2.so')
lib.tc_pair2.argtypes = [ctypes.c_void_p]*4 + [ctypes.c_int]*5 + [ctypes.c_void_p, ctypes.c_void_p]
def call(emb, W, bias, outs, nb, order=0, whint=0, nomma=0, prof=None):
    arr = (ctypes.c_void_p*6)(*[o.data_ptr() for o in outs])
    st = lib.tc_pair2(emb.data_ptr(), W.data_ptr(), bias.data_ptr(), arr, emb.shape[0], nb, order, whint, nomma,
                      prof.data_ptr() if prof is not None else None, torch.cuda.current_stream().cuda_stream)
    assert st == 0, st
torch.manual_seed(0)
W = torch.randn(18432, 3072, device='cuda') / 3072**0.5
bias = torch.randn(18432, device='cuda')
for B, nb in [(691,2),(919,2),(919,3),(449,1),(512,1),(384,1)]:
    emb = torch.randn(B, 3072, device='cuda')
    outs = [torch.zeros(B, 3072, device='cuda') for _ in range(6)]
    call(emb, W, bias, outs, nb); torch.cuda.synchronize()
    ref = (emb.double() @ W.double().t() + bias.double()).float()
    got = torch.cat(outs, 1)
    err = (got - ref).abs().max().item()
    print(B, nb, 'stages', lib.tc_pair2_stages(B, nb), 'maxerr %.3e' % err)

