lib = ctypes.CDLL('/tmp/e2/tc_pair2f.so'); lib.adamod_tc_pair2.argtypes = [ctypes.c_void_p]*4 + [ctypes.c_int]*2 + [ctypes.c_void_p]
g = {}
for tn in (192,256):
