        assert g[tn](emb.data_ptr(), W.data_ptr(), bias.data_ptr(), arr, emb.shape[0], 0, 148, torch.cuda.current_stream().cuda_stream) == 0
    return f
torch.manual_seed(2)
W = torch.randn(18432, 3072, device='cuda') / 3072**0.5
bias = torch.randn(18432, device='cuda')
for B in [691, 773, 853, 919, 373, 384, 449, 512]:
    emb = torch.randn(B, 3072, device='cuda'); outs = [torch.zeros(B, 3072, device='cuda') for _ in range(6)]
