    const uint32_t idesc = (1u << 4) | (2u << 7) | (2u << 10) | ((uint32_t)(Bpad >> 3) << 17) | ((uint32_t)(2 * kRows >> 4) << 24);
    for (int i = 0; i < nIt; ++i) {
      const int s = i % stages;
      mbar_wait(smem_u32(&full[s]), (i / stages) & 1);
      asm volatile("tcgen05.fence::after_thread_sync;");
      for (int j = 0; j < kbs; ++j) {
